create or replace function pg_temp.people_check(label text,ok boolean) returns void language plpgsql as $$begin
 if ok is distinct from true then raise exception 'Failed: %',label;end if;
 perform set_config('people_test.count',(coalesce(nullif(current_setting('people_test.count',true),''),'0')::int+1)::text,true);
end;$$;
create or replace function pg_temp.run_people_checks() returns jsonb language plpgsql as $test$
declare summary jsonb;
begin
 begin
 perform set_config('people_test.count','0',true);
insert into auth.users(id,email) select ('8f000000-0000-0000-0000-'||lpad(i::text,12,'0'))::uuid,'synthetic-'||i||'@example.invalid' from generate_series(1,6)i;
 insert into public.site_sites(id,slug,name) values('8f000000-0000-0000-0000-000000000010','people-security-test','Synthetic');
 insert into public.site_blocks(id,site_id,code) values('8f000000-0000-0000-0000-000000000011','8f000000-0000-0000-0000-000000000010','A');
 insert into public.site_units(id,site_id,block_id,number,code) values('8f000000-0000-0000-0000-000000000012','8f000000-0000-0000-0000-000000000010','8f000000-0000-0000-0000-000000000011',1,'A-1'),('8f000000-0000-0000-0000-000000000013','8f000000-0000-0000-0000-000000000010','8f000000-0000-0000-0000-000000000011',2,'A-2');
 insert into public.site_staff_memberships(site_id,user_id,role) values('8f000000-0000-0000-0000-000000000010','8f000000-0000-0000-0000-000000000001','manager'),('8f000000-0000-0000-0000-000000000010','8f000000-0000-0000-0000-000000000006','deputy');
 insert into public.ay2_permissions(site_id,user_id,capabilities) values('8f000000-0000-0000-0000-000000000010','8f000000-0000-0000-0000-000000000006',array['people','finance']);
 insert into public.ay2_settings(site_id,opening_cents,initialized) values('8f000000-0000-0000-0000-000000000010',100000,true);
 insert into public.ay3_persons(id,site_id,full_name,auth_user_id) values('8f000000-0000-0000-0000-000000000022','8f000000-0000-0000-0000-000000000010','Former synthetic','8f000000-0000-0000-0000-000000000002'),('8f000000-0000-0000-0000-000000000023','8f000000-0000-0000-0000-000000000010','Successor synthetic','8f000000-0000-0000-0000-000000000003'),('8f000000-0000-0000-0000-000000000024','8f000000-0000-0000-0000-000000000010','Representative synthetic','8f000000-0000-0000-0000-000000000004');
 insert into public.ay3_links(id,site_id,unit_id,person_id,role,active,starts_on,ends_on,archive_reason) values('8f000000-0000-0000-0000-000000000032','8f000000-0000-0000-0000-000000000010','8f000000-0000-0000-0000-000000000012','8f000000-0000-0000-0000-000000000022','tenant',false,'2018-01-01','2020-01-01','ended'),('8f000000-0000-0000-0000-000000000033','8f000000-0000-0000-0000-000000000010','8f000000-0000-0000-0000-000000000012','8f000000-0000-0000-0000-000000000023','tenant',true,'2021-01-01',null,null),('8f000000-0000-0000-0000-000000000034','8f000000-0000-0000-0000-000000000010','8f000000-0000-0000-0000-000000000012','8f000000-0000-0000-0000-000000000024','representative',true,'2021-01-01',null,null);
 insert into public.site_resident_units(unit_id,user_id,role,active) values('8f000000-0000-0000-0000-000000000012','8f000000-0000-0000-0000-000000000002','tenant',true);
 insert into public.ay2_charges(id,site_id,unit_id,person_id,link_id,category,label,due_on,cents,payer,reference,created_by) values('8f000000-0000-0000-0000-000000000042','8f000000-0000-0000-0000-000000000010','8f000000-0000-0000-0000-000000000012','8f000000-0000-0000-0000-000000000022','8f000000-0000-0000-0000-000000000032','Aidat','Former charge','2019-01-01',10000,'tenant','former','8f000000-0000-0000-0000-000000000001'),('8f000000-0000-0000-0000-000000000043','8f000000-0000-0000-0000-000000000010','8f000000-0000-0000-0000-000000000012','8f000000-0000-0000-0000-000000000023','8f000000-0000-0000-0000-000000000033','Aidat','Successor charge','2026-01-01',20000,'tenant','current','8f000000-0000-0000-0000-000000000001'),('8f000000-0000-0000-0000-000000000044','8f000000-0000-0000-0000-000000000010','8f000000-0000-0000-0000-000000000012',null,null,'Aidat','Unassigned','2026-01-01',30000,'review','unassigned','8f000000-0000-0000-0000-000000000001');
 insert into public.ay2_entries(id,site_id,booked_on,description,cents,dedup_key,created_by) values('8f000000-0000-0000-0000-000000000050','8f000000-0000-0000-0000-000000000010','2020-01-01','Secret bank text with third party',15000,'bank','8f000000-0000-0000-0000-000000000001');
 insert into public.ay2_allocations(site_id,entry_id,charge_id,request_id,cents,created_by) values('8f000000-0000-0000-0000-000000000010','8f000000-0000-0000-0000-000000000050','8f000000-0000-0000-0000-000000000042','8f000000-0000-0000-0000-000000000051',10000,'8f000000-0000-0000-0000-000000000001'),('8f000000-0000-0000-0000-000000000010','8f000000-0000-0000-0000-000000000050','8f000000-0000-0000-0000-000000000043','8f000000-0000-0000-0000-000000000052',5000,'8f000000-0000-0000-0000-000000000001');
 insert into public.ay3_credits(site_id,entry_id,unit_id,person_id,cents,request_id,created_by) values('8f000000-0000-0000-0000-000000000010','8f000000-0000-0000-0000-000000000050','8f000000-0000-0000-0000-000000000012','8f000000-0000-0000-0000-000000000022',1000,'8f000000-0000-0000-0000-000000000053','8f000000-0000-0000-0000-000000000001'),('8f000000-0000-0000-0000-000000000010','8f000000-0000-0000-0000-000000000050','8f000000-0000-0000-0000-000000000012','8f000000-0000-0000-0000-000000000023',2000,'8f000000-0000-0000-0000-000000000054','8f000000-0000-0000-0000-000000000001');
 insert into public.ay2_announcements(site_id,title,body,published,created_by) values('8f000000-0000-0000-0000-000000000010','Internal','Secret',true,'8f000000-0000-0000-0000-000000000001');
 insert into public.ay2_reports(site_id,period,opening_cents,income_cents,expense_cents,closing_cents,published_by) values('8f000000-0000-0000-0000-000000000010','2026-01-01',1,2,3,0,'8f000000-0000-0000-0000-000000000001');
reset role; set local role authenticated;perform set_config('request.jwt.claims','{"sub":"8f000000-0000-0000-0000-000000000002","role":"authenticated"}',true);
perform pg_temp.people_check('historical RLS site_sites',((select count(*) from public.site_sites)=1));
perform pg_temp.people_check('historical RLS site_units',((select count(*) from public.site_units)=1));
perform pg_temp.people_check('historical RLS ay2_charges',((select count(*) from public.ay2_charges)=1));
perform pg_temp.people_check('historical RLS ay2_allocations',((select count(*) from public.ay2_allocations)=1));
perform pg_temp.people_check('historical RLS ay3_credits',((select count(*) from public.ay3_credits)=1));
perform pg_temp.people_check('historical RLS ay2_entries',((select count(*) from public.ay2_entries)=0));
perform pg_temp.people_check('historical RLS ay2_reports',((select count(*) from public.ay2_reports)=0));
perform pg_temp.people_check('historical RLS ay2_announcements',((select count(*) from public.ay2_announcements)=0));
perform pg_temp.people_check('historical RLS ay2_settings',((select count(*) from public.ay2_settings)=0));
perform pg_temp.people_check('historical RLS ay2_audit',((select count(*) from public.ay2_audit)=0));
perform pg_temp.people_check('historical RLS ay3_match_rules',((select count(*) from public.ay3_match_rules)=0));
perform pg_temp.people_check('historical RLS ay3_providers',((select count(*) from public.ay3_providers)=0));
perform pg_temp.people_check('historical RLS ay3_provider_notes',((select count(*) from public.ay3_provider_notes)=0));
perform pg_temp.people_check('historical RLS ay2_staged_charges',((select count(*) from public.ay2_staged_charges)=0));
perform pg_temp.people_check('foreign person id cannot expand charge access',((select count(*) from public.ay2_charges where person_id='8f000000-0000-0000-0000-000000000023')=0));
perform pg_temp.people_check('no aggregate via summary RPC',(public.ay3_financial_summary('8f000000-0000-0000-0000-000000000010')='{}'::jsonb));
perform pg_temp.people_check('workspace is limited',((public.ay5_workspace('8f000000-0000-0000-0000-000000000010')->>'limited_access')::boolean));
perform pg_temp.people_check('workspace has one person',(jsonb_array_length(public.ay5_workspace('8f000000-0000-0000-0000-000000000010')->'persons')=1));
perform pg_temp.people_check('safe own payment amount',((public.ay5_workspace('8f000000-0000-0000-0000-000000000010')->'entries'->0->>'cents')::bigint=10000));
perform pg_temp.people_check('safe payment has no bank description',((public.ay5_workspace('8f000000-0000-0000-0000-000000000010')->'entries')::text not like '%Secret%'));
perform pg_temp.people_check('foreign site has no workspace',(public.ay5_workspace('8f000000-0000-0000-0000-000000000999') is null));
perform pg_temp.people_check('raw historical relationship notes hidden',((select count(*) from public.ay3_links)=0));
perform pg_temp.people_check('historical relationship projection omits notes',(jsonb_array_length(public.ay5_workspace('8f000000-0000-0000-0000-000000000010')->'links')=1 and not (public.ay5_workspace('8f000000-0000-0000-0000-000000000010')->'links'->0 ? 'archive_note')));
reset role; set local role authenticated;perform set_config('request.jwt.claims','{"sub":"8f000000-0000-0000-0000-000000000003","role":"authenticated"}',true);
perform pg_temp.people_check('successor cannot inherit former charge',((select count(*) from public.ay2_charges where id='8f000000-0000-0000-0000-000000000042')=0));
perform pg_temp.people_check('successor sees own charge',((select count(*) from public.ay2_charges)=1));
perform pg_temp.people_check('active account regular mode',(not (public.ay5_workspace('8f000000-0000-0000-0000-000000000010')->>'limited_access')::boolean));
reset role; set local role authenticated;perform set_config('request.jwt.claims','{"sub":"8f000000-0000-0000-0000-000000000004","role":"authenticated"}',true);
perform pg_temp.people_check('representative has no invented finance mandate',((select count(*) from public.ay2_charges)=0));
perform pg_temp.people_check('current representative notices from stored role',((select count(*) from public.ay2_announcements)=1));
reset role;update public.ay3_links set active=false,starts_on='2018-01-01',ends_on='2020-01-01' where id='8f000000-0000-0000-0000-000000000034';
reset role; set local role authenticated;perform set_config('request.jwt.claims','{"sub":"8f000000-0000-0000-0000-000000000004","role":"authenticated"}',true);
perform pg_temp.people_check('former representative no notices',((select count(*) from public.ay2_announcements)=0));
reset role; set local role authenticated;perform set_config('request.jwt.claims','{"sub":"8f000000-0000-0000-0000-000000000005","role":"authenticated"}',true);
perform pg_temp.people_check('stranger no site',((select count(*) from public.site_sites)=0));
perform pg_temp.people_check('stranger no charges',((select count(*) from public.ay2_charges)=0));
reset role; set local role authenticated;perform set_config('request.jwt.claims','{"sub":"8f000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
perform pg_temp.people_check('manager retains all charges',((select count(*) from public.ay2_charges)=3));
perform public.ay3_manage_person_v2('8f000000-0000-0000-0000-000000000010','8f000000-0000-0000-0000-000000000022','archive','Synthetic explicit revocation',true,true);
reset role; set local role authenticated;perform set_config('request.jwt.claims','{"sub":"8f000000-0000-0000-0000-000000000002","role":"authenticated"}',true);
perform pg_temp.people_check('explicitly revoked no history',((select count(*) from public.ay2_charges)=0));
perform pg_temp.people_check('explicitly revoked no site',((select count(*) from public.site_sites)=0));
reset role;update public.ay3_persons set access_revoked_at=null,archived_at=null where id='8f000000-0000-0000-0000-000000000022';update public.ay3_links set active=true,archived_at=null,ends_on=null where id='8f000000-0000-0000-0000-000000000032';
reset role; set local role authenticated;perform set_config('request.jwt.claims','{"sub":"8f000000-0000-0000-0000-000000000002","role":"authenticated"}',true);
perform pg_temp.people_check('return to active mode',(not (public.ay5_workspace('8f000000-0000-0000-0000-000000000010')->>'limited_access')::boolean));
reset role; set local role authenticated;perform set_config('request.jwt.claims','{"sub":"8f000000-0000-0000-0000-000000000006","role":"authenticated"}',true);
perform pg_temp.people_check('delegated finance retained',((select count(*) from public.ay2_charges)=3));
reset role;summary:=jsonb_build_object('passed',current_setting('people_test.count')::int,'failed',0,'scope','native staging PostgreSQL with actual production RLS read policies; synthetic changes rolled back');raise exception using errcode='PT001',message='rollback synthetic fixture';
 exception when sqlstate 'PT001' then return summary;end;
end;$test$;
select pg_temp.run_people_checks() result;
